  function settle(aborted){if(!pending)return;pending=false;if(aborted)cancel(handle);if(signal)signal.removeEventListener('abort',onAbort);if(aborted)reject(signal.reason);else resolve();}
  function onAbort(){settle(true);}
  handle=schedule(()=>settle(false),ms);if(signal)signal.addEventListener('abort',onAbort);
 });
